solution:
pub type Counter = { value: Int; }

impl Counter {
  fn decrement(self: &mut Self)
    requires: self.value > 0;
    ensures: self.value == self@pre.value - 1;
  { self.value = self.value - 1; }
}

fn main() -> Int {
  var c = Counter{ value: 5 };
  c.decrement();
  return c.value;
}
